      <h3 id="service-modal-title">Cadastrar Novo Serviço</h3>

      <form id="form-save-service" onsubmit="saveService(event)">
        <input type="hidden" id="service-id">
        <div class="form-group">
          <label for="service-name">Nome do Serviço</label>
          <input type="text" id="service-name" class="input-control" required placeholder="Ex: Corte de Cabelo, Limpeza, etc.">
        </div>
        <div class="form-group">
          <label for="service-description">Descrição Breve</label>
          <textarea id="service-description" class="input-control" rows="2" placeholder="Descreva os benefícios e o que está incluso"></textarea>
