          <button type="button" class="btn btn-secondary" onclick="closeServiceModal()">Cancelar</button>
          <button type="submit" class="btn btn-primary">Salvar Serviço</button>
        </div>
      </form>
    </div>
  </div>

  <script src="app.js"></script>
</body>
</html>

=== public/style.css ===
:root {
  --primary: #2563eb;
  --primary-hover: #1d4ed8;
  --primary-light: #eff6ff;
  --success: #16a34a;
  --warning: #d97706;
  --danger: #dc2626;
  --slate-900: #0f172a;
  --slate-800: #1e293b;
  --slate-700: #334155;
  --slate-600: #475569;
  --slate-500: #64748b;
  --slate-300: #cbd5e1;
  --slate-200: #e2e8f0;
  --slate-100: #f1f5f9;
  --slate-50: #f8fafc;
  --white: #ffffff;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -4px rgba(0, 0, 0, 0.1);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background-color: var(--slate-50);
  color: var(--slate-800);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* NAVBAR */
.navbar {
  background: var(--white);
  border-bottom: 1px solid var(--slate-200);
  position: sticky;
  top: 0;
  z-index: 40;
}

.nav-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0.85rem 1.25rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.brand {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  cursor: pointer;
  user-select: none;
}

.brand-icon {
  font-size: 1.5rem;
}

.brand-title {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--primary);
  letter-spacing: -0.5px;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.nav-btn {
  background: transparent;
  border: none;
  font-size: 0.95rem;
  font-weight: 500;
  color: var(--slate-700);
  padding: 0.5rem 0.85rem;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.2s ease;
}

.nav-btn:hover {
  background-color: var(--slate-100);
  color: var(--primary);
}

.user-badge {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  background-color: var(--slate-100);
  padding: 0.4rem 0.8rem;
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  font-weight: 600;
}

.admin-tag {
  background-color: #fef3c7;
  color: #b45309;
  font-size: 0.75rem;
  padding: 2px 6px;
  border-radius: 4px;
}

/* MAIN LAYOUT */
.main-container {
  max-width: 1100px;
  width: 100%;
  margin: 0 auto;
  padding: 2rem 1.25rem;
  flex: 1;
}

.view-section {
  display: none;
  animation: fadeIn 0.25s ease;
}

.view-section.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}

/* HERO SECTION */
.hero-card {
  background: linear-gradient(135deg, #1e3a8a, var(--primary));
  color: var(--white);
  padding: 3rem 2rem;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
  margin-bottom: 2.5rem;
  text-align: center;
}

.hero-card h1 {
  font-size: 2.2rem;
  font-weight: 700;
  margin-bottom: 0.75rem;
  letter-spacing: -0.5px;
}

.hero-card p {
  font-size: 1.1rem;
  opacity: 0.9;
  max-width: 600px;
  margin: 0 auto 1.5rem auto;
}

.hero-buttons {
  display: flex;
  justify-content: center;
  gap: 1rem;
  flex-wrap: wrap;
}

/* BUTTONS */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-weight: 600;
  font-size: 0.95rem;
  padding: 0.65rem 1.25rem;
  border-radius: var(--radius-md);
  border: 1px solid transparent;
  cursor: pointer;
  transition: all 0.2s ease;
  text-decoration: none;
}

.btn-primary {
  background-color: var(--primary);
  color: var(--white);
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.btn-primary:disabled {
  background-color: var(--slate-300);
  cursor: not-allowed;
}

.btn-secondary {
  background-color: var(--white);
  color: var(--slate-700);
  border-color: var(--slate-300);
}

.btn-secondary:hover {
  background-color: var(--slate-100);
}

.btn-outline {
  background: transparent;
  color: var(--primary);
  border-color: var(--primary);
}

.btn-outline:hover {
  background-color: var(--primary-light);
}

.btn-sm {
  padding: 0.35rem 0.75rem;
  font-size: 0.85rem;
}

.btn-block {
  width: 100%;
}

.btn-danger {
  background-color: #fee2e2;
  color: var(--danger);
  border-color: #fca5a5;
}

.btn-danger:hover {
  background-color: #fecaca;
}

.btn-success {
  background-color: #dcfce7;
  color: var(--success);
  border-color: #86efac;
}

.btn-success:hover {
  background-color: #bbf7d0;
}

/* SECTION HEADERS */
.section-title-wrap {
  margin-bottom: 1.5rem;
}

.section-title-wrap h2, .section-header h2 {
  font-size: 1.6rem;
  font-weight: 700;
  color: var(--slate-900);
}

.section-title-wrap p, .subtitle {
  color: var(--slate-500);
  margin-top: 0.25rem;
  font-size: 0.95rem;
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1.5rem;
  flex-wrap: wrap;
  gap: 1rem;
}

/* CARDS GRID */
.grid-cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 1.25rem;
}

.card {
  background: var(--white);
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-md);
  padding: 1.25rem;
  box-shadow: var(--shadow-sm);
  transition: transform 0.2s, box-shadow 0.2s;
}

.card:hover {
  box-shadow: var(--shadow-md);
}

.service-card {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.service-card h3 {
  font-size: 1.15rem;
  margin-bottom: 0.5rem;
  color: var(--slate-900);
}

.service-desc {
  color: var(--slate-600);
  font-size: 0.9rem;
  margin-bottom: 1rem;
  flex-grow: 1;
}

.service-meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-top: 1px solid var(--slate-100);
  padding-top: 0.75rem;
  margin-bottom: 1rem;
}

.service-price {
  font-size: 1.3rem;
  font-weight: 700;
  color: var(--slate-900);
}

.service-duration {
  font-size: 0.85rem;
  color: var(--slate-500);
  background: var(--slate-100);
  padding: 3px 8px;
  border-radius: 4px;
}

/* BOOKING FORM */
.booking-card {
  background: var(--white);
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-lg);
  padding: 2rem;
  box-shadow: var(--shadow-sm);
  max-width: 650px;
  margin: 0 auto;
}

.form-group {
  margin-bottom: 1.25rem;
}

.form-group label {
  display: block;
  font-size: 0.9rem;
  font-weight: 600;
  margin-bottom: 0.4rem;
  color: var(--slate-700);
}

.input-control {
  width: 100%;
  padding: 0.7rem 0.9rem;
  font-size: 0.95rem;
  border: 1px solid var(--slate-300);
  border-radius: var(--radius-md);
  background-color: var(--white);
  color: var(--slate-800);
  font-family: inherit;
  outline: none;
  transition: border-color 0.2s;
}

.input-control:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
}

.service-badge {
  background-color: var(--primary-light);
  color: var(--primary);
  padding: 0.5rem 0.8rem;
  border-radius: var(--radius-sm);
  font-size: 0.85rem;
  margin-top: 0.5rem;
  font-weight: 500;
}

.slots-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(80px, 1fr));
  gap: 0.5rem;
  margin-top: 0.5rem;
  max-height: 220px;
  overflow-y: auto;
  padding: 4px;
}

.slot-btn {
  padding: 0.6rem 0.4rem;
  font-size: 0.9rem;
  font-weight: 600;
  border: 1px solid var(--slate-300);
  background: var(--white);
  border-radius: var(--radius-sm);
  cursor: pointer;
  text-align: center;
  transition: all 0.15s ease;
}

.slot-btn:hover {
  border-color: var(--primary);
  color: var(--primary);
  background: var(--primary-light);
}

.slot-btn.selected {
  background: var(--primary);
  color: var(--white);
  border-color: var(--primary);
}

.slots-loading {
  font-size: 0.9rem;
  color: var(--slate-500);
  padding: 0.5rem 0;
}

.form-actions {
  display: flex;
  justify-content: flex-end;
  gap: 0.75rem;
  margin-top: 1.5rem;
}

/* LIST OF APPOINTMENTS */
.appointments-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.appointment-item {
  background: var(--white);
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-md);
  padding: 1.25rem;
  box-shadow: var(--shadow-sm);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

.appointment-info h4 {
  font-size: 1.1rem;
  color: var(--slate-900);
}

.appointment-info p {
  color: var(--slate-500);
  font-size: 0.9rem;
  margin-top: 0.2rem;
}

.appointment-status {
  padding: 4px 10px;
  border-radius: 9999px;
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
}

.status-pendente {
  background-color: #fef3c7;
  color: #b45309;
}

.status-confirmado {
  background-color: #dcfce7;
  color: #15803d;
}

.status-recusado {
  background-color: #fee2e2;
  color: #b91c1c;
}

.status-cancelado {
  background-color: var(--slate-200);
  color: var(--slate-600);
}

/* ADMIN PANEL */
.admin-topbar {
  margin-bottom: 1.5rem;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 1rem;
  margin-bottom: 1.5rem;
}

.stat-card {
  background: var(--white);
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-md);
  padding: 1.2rem;
  text-align: center;
}

.stat-label {
  display: block;
  font-size: 0.85rem;
  color: var(--slate-500);
  font-weight: 500;
  margin-bottom: 0.3rem;
}

.stat-value {
  font-size: 1.8rem;
  font-weight: 700;
  color: var(--slate-800);
}

.text-warning { color: var(--warning); }
.text-success { color: var(--success); }
.text-info { color: var(--primary); }

.admin-tabs {
  display: flex;
  gap: 0.5rem;
  border-bottom: 1px solid var(--slate-300);
  margin-bottom: 1.5rem;
  overflow-x: auto;
}

.tab-btn {
  background: transparent;
  border: none;
  padding: 0.75rem 1.2rem;
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--slate-500);
  cursor: pointer;
  border-bottom: 2px solid transparent;
  white-space: nowrap;
}

.tab-btn:hover {
